def get_permutations(s: str) -> list:
    if not s:
        return ['']
    chars = sorted(list(s))
    result = set()
    used = [False] * len(chars)

    def backtrack(path):
        if len(path) == len(chars):
            result.add(''.join(path))
            return
        for i in range(len(chars)):
            if not used[i]:
                used[i] = True
                path.append(chars[i])
                backtrack(path)
                path.pop()
                used[i] = False
    backtrack([])
    return sorted(list(result))
